// Identifica o documento do Autentique no payload do evento.
// ⚠️ Ajuste os caminhos conforme o payload real (veja a execução de teste no n8n).
const body = $json.body || $json;
const obj = (body.event && body.event.data && body.event.data.object) || (body.data && body.data.object) || body.object || {};
const documentId = (obj.document && (obj.document.id || obj.document)) || obj.document_id || obj.id || null;
const eventType = (body.event && body.event.type) || body.type || 'unknown';

if (!documentId) {
  // Evento sem documento identificável: encerra sem encaminhar.
  return [];
}
return [{ json: { documentId: String(documentId), eventType } }];
